import Heading from '@/shared/Heading'
import { TPost } from '@/types'
// import { ArrowRightIcon } from '@hugeicons/core-free-icons'
import clsx from 'clsx'
import Card3 from './PostCards/Card3'
import { Link } from '@tanstack/react-router'
import { ChevronRight, ChevronLeft } from 'lucide-react'
import { useOnline } from '@/hooks/use-online'
import NoInternet from './NoInternet'

const Latest = ({
  posts,
  heading,
  vr,
  loading,
  linkto,
  isBackgroundRefreshing,
}: {
  posts: TPost[]
  heading?: string
  vr: 'ar' | 'fr'
  loading?: boolean
  linkto?: string
  isBackgroundRefreshing?: boolean
}) => {
  const renderCard = (post: TPost, index: number) => {
    return <Card3 key={index} className="py-1" post={post} vr={vr} />
  }
  const { isOnline, checkConnection } = useOnline()

  const path = vr === 'fr' ? '/news/fr/$postId' : '/news/$postId'
  const link =
    linkto ??
    (vr === 'fr'
      ? 'dernieres-actualites'
      : decodeURIComponent(
          '%D8%A2%D8%AE%D8%B1-%D8%A7%D9%84%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1',
        ))

  if (loading)
    return (
      <div className="pt-4">
        <div className="space-y-6 lg:col-span-2">
          {Array.from({ length: 8 }).map((_, i) => (
            <div key={i} className="flex gap-4">
              <div className="h-50 w-56 rounded-lg bg-gray-300"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 w-3/4 rounded bg-gray-200"></div>
                <div className="h-4 w-full rounded bg-gray-200"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    )

  if (posts.length == 0) {
    checkConnection()
    return (
      <div className="w-full lg:w-3/5 xl:w-2/3 xl:pe-20 mx-auto">
        {!isOnline && (
          <NoInternet
            isFr={vr === 'fr'}
            isOnline={isOnline}
            onRetry={() => window.location.reload()}
            checkConnection={checkConnection}
          />
        )}
      </div>
    )
  }

  return (
    <div className="relative pt-4">
      {isBackgroundRefreshing && (
        <div className="absolute inset-0 z-10 flex items-start justify-center pt-2">
          <div className=" rounded-full bg-white px-4 py-2 shadow-md dark:bg-neutral-800">
            <svg
              className="h-4 w-4 animate-spin text-lime-500"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              />
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
              />
            </svg>
          </div>
        </div>
      )}
      {!!heading && (
        <Heading level={2}>
          <Link
            to={path}
            params={{ postId: link }}
            className="flex items-center space-x-4 "
          >
            {heading}
            {vr === 'fr' ? (
              <ChevronRight size={19} strokeWidth={3} className="mt-1" />
            ) : (
              <ChevronLeft size={19} strokeWidth={3} className="mt-1" />
            )}{' '}
          </Link>
        </Heading>
      )}
      <div className={clsx('grid gap-6 md:gap-7')}>{posts.map(renderCard)}</div>
    </div>
  )
}

export default Latest
