import { shuffle } from '@/config'
import { originToUsable, TUnPost } from '@/data/posts'
import { TPost } from '@/types'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useEffect, useState } from 'react'
import { getLastFetchTime, getLsKey, setLastFetchTime } from './utils'

const api = import.meta.env.VITE_API_NEWS

const LS_PREFIX = 'cat'
const STALE_THRESHOLD_MS = 10 * 60 * 1000 // 10 minutes

export const useGetPostByCat = (
  cat?: number,
  page?: string | number,
  rand?: boolean,
  bgRefresh?: boolean,
) => {
  const queryClient = useQueryClient()
  const [isBackgroundRefreshing, setIsBackgroundRefreshing] = useState(false)
  const queryKey = ['cat', { cat, page, rand: !!rand }]
  const query = useQuery({
    enabled: !!cat,
    staleTime: 1000 * 600,
    queryKey,
    queryFn: async () => {
      const response = await fetch(`${api}/categorie/${cat}?p=${page}`)

      if (!response.ok) {
        throw new Error('faild to fetch posts')
      }

      const { results: unformatedPosts, total }: categorieResponse =
        await response.json()

      const beforeRandPosts: TPost[] = unformatedPosts.map((post) =>
        originToUsable(post),
      )

      const posts = rand ? shuffle(beforeRandPosts) : beforeRandPosts
      return { posts, total }
    },
  })

  useEffect(() => {
    if (!bgRefresh || !query.isSuccess || query.isFetching) return

    const lsKey = getLsKey(LS_PREFIX, String(cat!), String(page), rand)
    const lastFetch = getLastFetchTime(lsKey)

    if (lastFetch === null) {
      setLastFetchTime(lsKey)
      return
    }
    if (Date.now() - lastFetch < STALE_THRESHOLD_MS) return

    // Stamp immediately to prevent duplicate fetches across re-renders
    setLastFetchTime(lsKey)

    const controller = new AbortController()
    setIsBackgroundRefreshing(true)

    fetch(`${api}/categorie/${cat}?p=${page}&_cb=${Date.now()}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) throw new Error('bg refresh failed')
        return res.json()
      })
      .then(({ results: unformatedPosts, total }: categorieResponse) => {
        const beforeRandPosts: TPost[] = unformatedPosts.map((post) =>
          originToUsable(post),
        )
        const posts = rand ? shuffle(beforeRandPosts) : beforeRandPosts
        if (posts.length > 0) {
          queryClient.setQueryData(queryKey, { posts, total })
        }
      })
      .catch((err) => {
        if (err.name !== 'AbortError') {
          console.error('Background refresh failed', err)
        }
      })
      .finally(() => setIsBackgroundRefreshing(false))

    return () => controller.abort()
  }, [
    bgRefresh,
    query.isSuccess,
    query.isFetching,
    cat,
    page,
    rand,
    queryClient,
  ])

  return { ...query, isBackgroundRefreshing }
}

export interface categorieResponse {
  page: number
  pageSize: number
  total: number
  results: TUnPost[]
}
